// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the list length and a dummy recipient index to build valid calldata
    function testFuzz_property(uint256 len, uint256 seed) public {
        // keep length reasonable but allow zero to be excluded by contract require
        uint256 n = bound(len, 0, 8);

        // build arrays for _tos and v of length n (must be >0 for admissible inputs)
        address[] memory tos = new address[](n);
        uint256[] memory vals = new uint256[](n);

        // use a benign callee that will accept the low-level call; the original contract
        // uses a fixed caddress, but we only call transfer which does low-level call to that
        // fixed address; since we cannot change c.caddress, we just supply arrays such that
        // if n==0 the call would revert; ensure we exercise non-reverting path by requiring n>0

        // choose arbitrary addresses (EOAs) and small positive values
        for (uint256 i = 0; i < n; i++) {
            // derive pseudorandom addresses from seed to let fuzzer vary them
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(seed, i)))));
            // nonzero amounts to avoid any potential zero-edge semantics
            vals[i] = (uint256(keccak256(abi.encodePacked(seed, i, "v"))) % 10) + 1;
        }

        // The reference contract requires _tos.length > 0. We only assert the universal property
        // for admissible inputs. If n == 0 then transfer will revert; we skip asserting in that case
        if (n == 0) return;

        // call transfer and capture whether it returned (did not revert) and the boolean return value
        bool ok;
        bool ret;
        try c.transfer(tos, vals) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // General rule: for every admissible input where transfer completes (ok == true), the reference
        // implementation returns true. We express this by asserting that if the call completed then ret == true.
        // This will pass on the reference and fail on the mutant for some inputs where it completes but returns false.
        assertTrue(!ok || ret);
    }
}

