pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the arrays' length and a single element value; we deploy a benign callee
    // that always succeeds so the transfer loop completes. We assert that
    // the call to transfer returns true (which the reference satisfies for all
    // completing calls) — the mutant that returns false will fail this test for some inputs.
    function testFuzz_property(uint8 len, uint256 v0) public {
        // keep length in a reasonable but wide bound: 1..5 (must be >0 to satisfy contract require)
        uint256 length = bound(len, 1, 5);

        // build arrays
        address[] memory tos = new address[](length);
        uint[] memory vals = new uint[](length);

        // deploy a helper callee that always returns true on call (non-reverting)
        GoodCallee g = new GoodCallee();
        for (uint i = 0; i < length; i++) {
            tos[i] = address(g); // route all external calls to the helper so c.call(...) succeeds
            vals[i] = v0; // same fuzzed value for each element
        }

        // Make the caller the required msg.sender
        address requiredSender = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        // Give requiredSender some balance so it can execute if needed (though no value is sent)
        vm.deal(requiredSender, 1 ether);
        vm.prank(requiredSender);

        // Call transfer and capture whether it returns true/false via try/catch
        bool ok;
        try c.transfer(tos, vals) returns (bool r) {
            ok = r;
        } catch {
            // If it reverts, mark as false. The property is about completing calls; we keep domain wide so revert cases are allowed but will set ok=false.
            ok = false;
        }

        // The universal property: for any admissible inputs (we allowed len>=1 and arbitrary v0),
        // the reference returns true for completing calls. This assertTrue reads c's behavior via the call result.
        assertTrue(ok);
    }
}

// Minimal helper that always accepts the call and returns successfully.
contract GoodCallee {
    fallback() external payable {
        // do nothing, succeed
    }
    receive() external payable {
        // accept ETH
    }
}

