pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // adversarial helper that accepts calls and always succeeds
    // (we need a contract with code so low-level call to it can succeed and return data)
    contract Succeeds {
        fallback() external payable {}
        function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    }
    Succeeds helper;

    function setUp() public { 
        c = new C();
        helper = new Succeeds();
    }

    // fuzzed params: length and a value; we will construct _tos and v arrays
    function testFuzz_property(uint8 len, uint256 val) public {
        // keep length in a reasonable non-zero range because C.requires _tos.length > 0
        uint256 n = bound(len, 1, 10);

        address[] memory tos = new address[](n);
        uint[] memory vs = new uint[](n);
        for (uint i = 0; i < n; i++) {
            tos[i] = address(helper); // route c's external calls to our helper which succeeds
            vs[i] = val;
        }

        // call as the designated sender
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool ok;
        // capture whether the call completes (doesn't revert) and also capture return
        try c.transfer(tos, vs) returns (bool ret) {
            ok = ret; // record returned boolean
        } catch {
            ok = false; // if it reverts treat as false
        }

        // For the reference C, when call does not revert it must return true.
        // Because our helper always succeeds, the call should not revert; assert that the returned value is true.
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Callee helper;

    function setUp() public { c = new C(); helper = new Callee(); }

    // fuzzed params: an array length and a single value and an address actor (will be pranked to match the required sender)
    function testFuzz_property(uint8 len, uint256 v, address actor) public {
        // keep length reasonable but allow zero to be filtered by require in transfer
        uint256 l = bound(len, 0, 10);

        // build _tos array of length l filled with the deployed helper address so external calls succeed
        address[] memory tos = new address[](l);
        for (uint256 i = 0; i < l; i++) tos[i] = address(helper);

        uint[] memory vals = new uint[](l);
        for (uint256 i = 0; i < l; i++) vals[i] = v;

        // the reference contract requires msg.sender to be a specific hardcoded address; fuzz actor must match it
        address requiredSender = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

        // only meaningful when actor equals the required sender and length > 0; allow fuzzer to hit that
        vm.assume(actor == requiredSender);

        bool ok;
        // call transfer as the required sender; capture whether it returns (completes) and the returned value
        vm.prank(actor);
        try c.transfer(tos, vals) returns (bool ret) {
            // completed and returned a value
            ok = ret;
        } catch {
            // reverted
            ok = false;
        }

        // General rule: for any admissible input (designated sender, non-empty tos, helper succeeds), reference returns true.
        // We assert that c.transfer(...) returned true for this call. The mutant that always returns false will fail this assertion
        // for some inputs (specifically when actor == requiredSender and l > 0).
        if (l > 0) {
            assertTrue(ok);
        } else {
            // when l == 0 the reference reverts (require), so we don't assert on that case; keep domain wide
            assertTrue(true);
        }
    }
}

// helper callee that always succeeds on the low-level call
contract Callee {
    // emulate ERC20-like transferFrom success by providing a payable fallback that returns successfully
    fallback() external payable {
        // do nothing, succeed
    }
    receive() external payable {}
}
